"""Prepare registered source-only equal-view-budget coverage controls."""
import json,shutil
from pathlib import Path
from radio_gs.geometry.registered_pinhole import blender_camera_to_opencv,load_registered_camera_table
from radio_gs.utils.immutable_artifacts import sha256_file
config=Path('configs/experiments/scannet_geometry_coverage16_20260919.json');plan=json.loads(config.read_text())
for row in plan['scenes']:
 scene=row['scene'];root=Path('output/scannet_coverage_native_probe_20260919')/scene;root.mkdir(parents=True,exist_ok=False);base=root/'base';base.mkdir();rgb=root/'source_rgb';rgb.mkdir();original=Path('output/scannet_frozen_field_20260918')/scene;gr=json.loads((original/'geometry_report.json').read_text());g=gr['results']['independent_scale'];assert sha256_file(g['geometry'])==row['geometry_sha256']==g['geometry_sha256'];old=json.loads(Path(gr['source_report']).read_text());source_path=Path(old['source_camera_file']);assert sha256_file(source_path)==old['source_camera_sha256'];source=json.loads(source_path.read_text());frames_by_id={int(Path(f['file_path']).stem):f for f in source['frames']};train=sorted(row['train_frames']);validation=row['validation_frames'];assert len(train)==16 and not set(train)&set(validation);frames=train+validation;records=[];images=[]
 for fid in frames:
  f=frames_by_id[fid];c=blender_camera_to_opencv(f,source);image=source_path.parent/('color/'+str(fid)+'.jpg');assert image.exists();digest=sha256_file(image);records.append(dict(frame_index=fid,source_image=str(image),source_sha256=digest,**{k:(v.tolist() if hasattr(v,'tolist') else v) for k,v in c.items()}));shutil.copy2(image,rgb/image.name);images.append(dict(image_id=f'frame_{fid:05d}',path=str(image),sha256=digest,rgb_role='registered_source_or_mapping_view'))
 camera=dict(old,records=records,source_frame_indices=frames,selection='Predeclared source-only mesh visibility coverage; train16, original validation2; no semantic labels or benchmark queries',source_training_views=True,semantic_labels_opened=False,benchmark_queries_used=False,implementation_sha256=sha256_file(__file__))
 cp=root/'source_authority.json';cp.write_text(json.dumps(camera,indent=2)+'\n');assert set(load_registered_camera_table(cp))==set(frames)
 sam=root/'sam_rgb_authority.json';sam.write_text(json.dumps(dict(schema_version=1,contract='sam3-query-free-source-rgb-authority-v1',information_policy=dict(registered_source_rgb_only=True,query_text_used=False,benchmark_ground_truth_used=False,target_or_evaluation_rgb_used=False),images=images),indent=2)+'\n')
 gr.update(source_report=str(cp.resolve()),source_report_sha256=sha256_file(cp),mapping_frames=frames,coverage_control_registration_sha256=sha256_file(config),same_geometry_sha256_as_frozen_baseline=g['geometry_sha256']);(root/'geometry_report.json').write_text(json.dumps(gr,indent=2)+'\n')
 (base/'source_plan.json').write_text(json.dumps(dict(scene=scene,frames=frames,train_frames=train,validation_frames=validation,radio_root=str((root/'radio').resolve()),benchmark_data_used=False,source_authority=dict(path=str(sam.resolve()),sha256=sha256_file(sam)),selection=camera['selection'],registration_sha256=sha256_file(config)),indent=2)+'\n')
 (root/'execution.json').write_text(json.dumps(dict(scene=scene,complete=False,native_classification_only=True,full_method_rebuilt=False,stages=[]),indent=2)+'\n');print(root)
